    65→// 랜덤 초기화 (Xavier)
    66→func (t *Tensor) InitXavier(in, out int) {
    67→	scale := math.Sqrt(2.0 / float64(in+out))
    68→	for i := range t.data {
    69→		// 단순 균등분포 (정규분포는 생략)
    70→		t.data[i] = (math.Sin(float64(i*17%1000)) * scale) - scale/2
    71→	}
    72→}
