    90→// 행렬곱 (간단한 구현)
    91→func MatMul(a, b *Tensor) *Tensor {
    92→	// a: [M, K], b: [K, N] → [M, N]
    93→	M, K := a.shape[0], a.shape[1]
    94→	N := b.shape[1]
