   140→
   141→	bias := &Parameter{
   142→		data: NewTensor([]int{out}),
   143→		grad: NewTensor([]int{out}),
   144→	}
   145→
   146→	return &Linear{
   147→		weight: weight,
   148→		bias:   bias,
   149→		in:     in,
   150→		out:    out,
   151→	}
   152→}
   153→
   154→// 선형 레이어 포워드
   155→func (l *Linear) Forward(x *Tensor) *Tensor {
   156→	// x: [batch, in] → [batch, out]
   157→	// y = x @ W^T + b
   158→
   159→	batch := x.shape[0]
   160→	weightT := NewTensor([]int{l.in, l.out})
   161→
   162→	// 전치
   163→	for i := 0; i < l.in; i++ {
   164→		for j := 0; j < l.out; j++ {
   165→			weightT.Set(i, j, l.weight.data.Get(j, i))
   166→		}
   167→	}
   168→
   169→	// 행렬곱
   170→	y := MatMul(x, weightT)
   171→
   172→	// 편향 더하기
   173→	for i := 0; i < batch; i++ {
   174→		for j := 0; j < l.out; j++ {
   175→			y.Set(i, j, y.Get(i, j)+l.bias.data.data[j])
   176→		}
   177→	}
   178→
   179→	return y
   180→}
   181→
   182→// ==================================================
   183→// 활성화 함수
   184→// ==================================================
   185→
   186→// ReLU
   187→func ReLU(x *Tensor) *Tensor {
   188→	result := NewTensor(x.shape)
   189→	for i, v := range x.data {
   190→		if v > 0 {
   191→			result.data[i] = v
   192→		}
   193→	}
