   197→// Softmax (수치 안정성)
   198→func Softmax(x *Tensor) *Tensor {
   199→	// x: [batch, vocab]
   200→	result := NewTensor(x.shape)
   201→	batch := x.shape[0]
   202→	vocab := x.shape[1]
   203→
   204→	for b := 0; b < batch; b++ {
   205→		// Max 찾기
   206→		max := x.Get(b, 0)
   207→		for v := 0; v < vocab; v++ {
   208→			if x.Get(b, v) > max {
   209→				max = x.Get(b, v)
   210→			}
   211→		}
   212→
   213→		// Exp 합
   214→		sumExp := 0.0
   215→		for v := 0; v < vocab; v++ {
   216→			sumExp += math.Exp(x.Get(b, v) - max)
   217→		}
   218→
   219→		// Softmax
   220→		for v := 0; v < vocab; v++ {
   221→			prob := math.Exp(x.Get(b, v)-max) / sumExp
   222→			result.Set(b, v, prob)
   223→		}
   224→	}
   225→
   226→	return result
   227→}
   228→
   229→// ==================================================
   230→// 손실 함수
   231→// ==================================================
   232→
   233→// Cross-entropy loss
   234→func CrossEntropyLoss(logits, targets *Tensor) float64 {
   235→	// logits: [batch, vocab]
   236→	// targets: [batch] (인덱스)
   237→	// 출력: scalar loss
