   244→		targetIdx := int(targets.data[b])
   245→		if targetIdx >= 0 && targetIdx < logits.shape[1] {
   246→			prob := probs.Get(b, targetIdx)
   247→			if prob > 0 {
   248→				totalLoss += -math.Log(prob)
   249→			}
   250→		}
   251→	}
   252→
   253→	return totalLoss / float64(batch)
   254→}
   255→
   256→// ==================================================
   257→// 옵티마이저 (Adam)
   258→// ==================================================
   259→
   260→type Adam struct {
   261→	lr    float64
   262→	beta1 float64
   263→	beta2 float64
   264→	eps   float64
   265→	t     int64
   266→	m     map[*Tensor]*Tensor // 첫 번째 모멘트
   267→	v     map[*Tensor]*Tensor // 두 번째 모멘트
   268→}
   269→
   270→func NewAdam(lr float64) *Adam {
   271→	return &Adam{
   272→		lr:    lr,
   273→		beta1: 0.9,
   274→		beta2: 0.999,
   275→		eps:   1e-8,
   276→		t:     0,
   277→		m:     make(map[*Tensor]*Tensor),
   278→		v:     make(map[*Tensor]*Tensor),
   279→	}
   280→}
   281→
   282→// Adam 스텝 (간단한 구현)
   283→func (opt *Adam) Step(params []*Parameter) {
   284→	opt.t++
   285→
   286→	for _, param := range params {
   287→		w := param.data
   288→		g := param.grad
   289→
   290→		// m_t, v_t 초기화
   291→		if _, ok := opt.m[w]; !ok {
   292→			opt.m[w] = NewTensor(w.shape)
   293→			opt.v[w] = NewTensor(w.shape)
   294→		}
   295→
   296→		m := opt.m[w]
   297→		v := opt.v[w]
   298→
   299→		// 업데이트
   300→		for i := range w.data {
   301→			// m_t = β₁*m + (1-β₁)*g
   302→			m.data[i] = opt.beta1*m.data[i] + (1-opt.beta1)*g.data[i]
   303→
   304→			// v_t = β₂*v + (1-β₂)*g²
   305→			v.data[i] = opt.beta2*v.data[i] + (1-opt.beta2)*g.data[i]*g.data[i]
   306→
   307→			// Bias correction
   308→			mHat := m.data[i] / (1 - math.Pow(opt.beta1, float64(opt.t)))
   309→			vHat := v.data[i] / (1 - math.Pow(opt.beta2, float64(opt.t)))
   310→
   311→			// 파라미터 업데이트
   312→			w.data[i] -= opt.lr * mHat / (math.Sqrt(vHat) + opt.eps)
   313→		}
   314→	}
   315→}
   316→
   317→// ==================================================
   318→// 간단한 임베딩
   319→// ==================================================
   320→
   321→type Embedding struct {
   322→	weight *Parameter
   323→}
   324→
   325→func NewEmbedding(vocabSize, dimModel int) *Embedding {
   326→	weight := &Parameter{
