package main

import (
	"math"
)

// ==================================================
// Phase D: GPT 모델 구조 (Go 구현)
// ==================================================

// 텐서 (1D 평탄화)
type Tensor struct {
	data   []float64
	shape  []int
	size   int
}

// 파라미터 (requires_grad 포함)
type Parameter struct {
	data  *Tensor
	grad  *Tensor
}

// 선형 레이어
type Linear struct {
	weight *Parameter
	bias   *Parameter
	in     int
	out    int
}

// 레이어 정규화
type LayerNorm struct {
	weight *Parameter
	bias   *Parameter
	eps    float64
}

// GPT 설정
type GPTConfig struct {
	VocabSize int
	DModel    int
	NumHeads  int
	NumLayers int
	MaxSeqLen int
}

// ==================================================
// 유틸리티
// ==================================================

// 텐서 생성
func NewTensor(shape []int) *Tensor {
	size := 1
	for _, d := range shape {
		size *= d
	}
	return &Tensor{
		data:  make([]float64, size),
		shape: shape,
		size:  size,
	}
}

// 랜덤 초기화 (Xavier)
func (t *Tensor) InitXavier(in, out int) {
	scale := math.Sqrt(2.0 / float64(in+out))
	for i := range t.data {
		// 단순 균등분포 (정규분포는 생략)
		t.data[i] = (math.Sin(float64(i*17%1000)) * scale) - scale/2
	}
}

// 인덱스 접근 (2D)
func (t *Tensor) Get(i, j int) float64 {
	idx := i*t.shape[1] + j
	if idx < len(t.data) {
		return t.data[idx]
	}
	return 0
}

func (t *Tensor) Set(i, j int, val float64) {
	idx := i*t.shape[1] + j
	if idx < len(t.data) {
		t.data[idx] = val
	}
}

// 행렬곱 (간단한 구현)
func MatMul(a, b *Tensor) *Tensor {
	// a: [M, K], b: [K, N] → [M, N]
	M, K := a.shape[0], a.shape[1]
	N := b.shape[1]

	result := NewTensor([]int{M, N})

	for i := 0; i < M; i++ {
		for j := 0; j < N; j++ {
			sum := 0.0
			for k := 0; k < K; k++ {
				sum += a.Get(i, k) * b.Get(k, j)
			}
			result.Set(i, j, sum)
		}
	}

	return result
}

// 덧셈
func Add(a, b *Tensor) *Tensor {
	result := NewTensor(a.shape)
	for i := range a.data {
		result.data[i] = a.data[i] + b.data[i]
	}
	return result
}

// 스칼라 곱
func Scale(t *Tensor, scalar float64) *Tensor {
	result := NewTensor(t.shape)
	for i, v := range t.data {
		result.data[i] = v * scalar
	}
	return result
}

// ==================================================
// 신경망 레이어
// ==================================================

// 선형 레이어 생성
func NewLinear(in, out int) *Linear {
	weight := &Parameter{
		data: NewTensor([]int{out, in}),
		grad: NewTensor([]int{out, in}),
	}
	weight.data.InitXavier(in, out)

	bias := &Parameter{
		data: NewTensor([]int{out}),
		grad: NewTensor([]int{out}),
	}

	return &Linear{
		weight: weight,
		bias:   bias,
		in:     in,
		out:    out,
	}
}

// 선형 레이어 포워드
func (l *Linear) Forward(x *Tensor) *Tensor {
	// x: [batch, in] → [batch, out]
	// y = x @ W^T + b

	batch := x.shape[0]
	weightT := NewTensor([]int{l.in, l.out})

	// 전치
	for i := 0; i < l.in; i++ {
		for j := 0; j < l.out; j++ {
			weightT.Set(i, j, l.weight.data.Get(j, i))
		}
	}

	// 행렬곱
	y := MatMul(x, weightT)

	// 편향 더하기
	for i := 0; i < batch; i++ {
		for j := 0; j < l.out; j++ {
			y.Set(i, j, y.Get(i, j)+l.bias.data.data[j])
		}
	}

	return y
}

// ==================================================
// 활성화 함수
// ==================================================

// ReLU
func ReLU(x *Tensor) *Tensor {
	result := NewTensor(x.shape)
	for i, v := range x.data {
		if v > 0 {
			result.data[i] = v
		}
	}
	return result
}

// Softmax (수치 안정성)
func Softmax(x *Tensor) *Tensor {
	// x: [batch, vocab]
	result := NewTensor(x.shape)
	batch := x.shape[0]
	vocab := x.shape[1]

	for b := 0; b < batch; b++ {
		// Max 찾기
		max := x.Get(b, 0)
		for v := 0; v < vocab; v++ {
			if x.Get(b, v) > max {
				max = x.Get(b, v)
			}
		}

		// Exp 합
		sumExp := 0.0
		for v := 0; v < vocab; v++ {
			sumExp += math.Exp(x.Get(b, v) - max)
		}

		// Softmax
		for v := 0; v < vocab; v++ {
			prob := math.Exp(x.Get(b, v)-max) / sumExp
			result.Set(b, v, prob)
		}
	}

	return result
}

// ==================================================
// 손실 함수
// ==================================================

// Cross-entropy loss
func CrossEntropyLoss(logits, targets *Tensor) float64 {
	// logits: [batch, vocab]
	// targets: [batch] (인덱스)
	// 출력: scalar loss

	batch := logits.shape[0]
	probs := Softmax(logits)

	totalLoss := 0.0
	for b := 0; b < batch; b++ {
		targetIdx := int(targets.data[b])
		if targetIdx >= 0 && targetIdx < logits.shape[1] {
			prob := probs.Get(b, targetIdx)
			if prob > 0 {
				totalLoss += -math.Log(prob)
			}
		}
	}

	return totalLoss / float64(batch)
}

// ==================================================
// 옵티마이저 (Adam)
// ==================================================

type Adam struct {
	lr    float64
	beta1 float64
	beta2 float64
	eps   float64
	t     int64
	m     map[*Tensor]*Tensor // 첫 번째 모멘트
	v     map[*Tensor]*Tensor // 두 번째 모멘트
}

func NewAdam(lr float64) *Adam {
	return &Adam{
		lr:    lr,
		beta1: 0.9,
		beta2: 0.999,
		eps:   1e-8,
		t:     0,
		m:     make(map[*Tensor]*Tensor),
		v:     make(map[*Tensor]*Tensor),
	}
}

// Adam 스텝 (간단한 구현)
func (opt *Adam) Step(params []*Parameter) {
	opt.t++

	for _, param := range params {
		w := param.data
		g := param.grad

		// m_t, v_t 초기화
		if _, ok := opt.m[w]; !ok {
			opt.m[w] = NewTensor(w.shape)
			opt.v[w] = NewTensor(w.shape)
		}

		m := opt.m[w]
		v := opt.v[w]

		// 업데이트
		for i := range w.data {
			// m_t = β₁*m + (1-β₁)*g
			m.data[i] = opt.beta1*m.data[i] + (1-opt.beta1)*g.data[i]

			// v_t = β₂*v + (1-β₂)*g²
			v.data[i] = opt.beta2*v.data[i] + (1-opt.beta2)*g.data[i]*g.data[i]

			// Bias correction
			mHat := m.data[i] / (1 - math.Pow(opt.beta1, float64(opt.t)))
			vHat := v.data[i] / (1 - math.Pow(opt.beta2, float64(opt.t)))

			// 파라미터 업데이트
			w.data[i] -= opt.lr * mHat / (math.Sqrt(vHat) + opt.eps)
		}
	}
}

// ==================================================
// 간단한 임베딩
// ==================================================

type Embedding struct {
	weight *Parameter
}

func NewEmbedding(vocabSize, dimModel int) *Embedding {
	weight := &Parameter{
		data: NewTensor([]int{vocabSize, dimModel}),
		grad: NewTensor([]int{vocabSize, dimModel}),
	}
	weight.data.InitXavier(vocabSize, dimModel)
	return &Embedding{weight: weight}
}

// Forward: [batch, seq] → [batch, seq, dim]
func (e *Embedding) Forward(tokenIds [][]int, seqLen, dim int) *Tensor {
	batch := len(tokenIds)
	result := NewTensor([]int{batch, seqLen, dim})

	// 간단한 구현: 각 토큰의 임베딩을 복사
	for b := 0; b < batch; b++ {
		for s := 0; s < seqLen && s < len(tokenIds[b]); s++ {
			tokenID := tokenIds[b][s]
			if tokenID >= 0 && tokenID < e.weight.data.shape[0] {
				for d := 0; d < dim; d++ {
					idx := (b*seqLen+s)*dim + d
					result.data[idx] = e.weight.data.Get(tokenID, d)
				}
			}
		}
	}

	return result
}

package main

import (
	"fmt"
	"math"
	"math/rand"
	"time"
)

// ==================================================
// 서버 내 지속 학습 시스템
// ==================================================

// TrainingConfig 학습 설정
type TrainingConfig struct {
	VocabSize      int
	DModel         int
	BatchSize      int
	LearningRate   float64
	Epochs         int
	ValidateEvery  int
	SaveEvery      int
	MaxGradNorm    float64
	WeightDecay    float64
	WarmupSteps    int
}

// TrainingState 학습 상태
type TrainingState struct {
	Step           int64
	Epoch          int
	TotalLoss      float64
	BatchLoss      float64
	ValLoss        float64
	BestValLoss    float64
	LearningRate   float64
	GradNorm       float64
	PatienceCount  int
	StartTime      time.Time
	LastSaveTime   time.Time
}

// TrainingMetrics 학습 메트릭
type TrainingMetrics struct {
	Step        int64
	Epoch       int
	Loss        float64
	ValLoss     float64
	LearningRate float64
	GradNorm    float64
	Speed       float64 // steps/sec
	ETA         string
	Improvement float64
}

// Trainer 학습기
type Trainer struct {
	Config  TrainingConfig
	State   TrainingState
	Model   *EmbeddingModel
	Optimizer *Adam
	BestModel *EmbeddingModel
}

// NewTrainer 새로운 학습기 생성
func NewTrainer(config TrainingConfig) *Trainer {
	model := NewEmbeddingModel(config.VocabSize, config.DModel)
	optimizer := NewAdam(config.LearningRate, 0.9, 0.999, 1e-8)

	return &Trainer{
		Config: config,
		State: TrainingState{
			Step:         0,
			Epoch:        0,
			BestValLoss:  math.Inf(1),
			StartTime:    time.Now(),
			LastSaveTime: time.Now(),
		},
		Model:     model,
		Optimizer: optimizer,
		BestModel: model.Clone(),
	}
}

// Train 학습 실행
func (t *Trainer) Train(batches [][][]int, valBatches [][][]int) {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Continuous Training System            ║")
	fmt.Println("║  Server-side Learning Program                         ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	fmt.Printf("[CONFIG]\n")
	fmt.Printf("  VocabSize:     %d\n", t.Config.VocabSize)
	fmt.Printf("  DModel:        %d\n", t.Config.DModel)
	fmt.Printf("  BatchSize:     %d\n", t.Config.BatchSize)
	fmt.Printf("  LearningRate:  %.6f\n", t.Config.LearningRate)
	fmt.Printf("  Epochs:        %d\n", t.Config.Epochs)
	fmt.Printf("  WeightDecay:   %.6f\n", t.Config.WeightDecay)
	fmt.Printf("  WarmupSteps:   %d\n\n", t.Config.WarmupSteps)

	for epoch := 1; epoch <= t.Config.Epochs; epoch++ {
		t.State.Epoch = epoch
		epochLoss := t.trainEpoch(batches)
		fmt.Printf("\n--- Epoch %d/%d ---\n", epoch, t.Config.Epochs)
		fmt.Printf("  Train Loss: %.4f\n", epochLoss)

		// 검증
		if epoch%1 == 0 {
			valLoss := t.validateEpoch(valBatches)
			t.State.ValLoss = valLoss
			fmt.Printf("  Val Loss:   %.4f", valLoss)

			// 최고 모델 저장
			if valLoss < t.State.BestValLoss {
				improvement := (t.State.BestValLoss - valLoss) / t.State.BestValLoss * 100
				fmt.Printf("  📈 %.2f%% improvement\n", improvement)
				t.State.BestValLoss = valLoss
				t.BestModel = t.Model.Clone()
				t.State.PatienceCount = 0
			} else {
				t.State.PatienceCount++
				fmt.Printf("  (patience: %d/3)\n", t.State.PatienceCount)

				// 조기 종료
				if t.State.PatienceCount >= 3 {
					fmt.Printf("\n⚠️ Early stopping at epoch %d\n", epoch)
					break
				}
			}
		}
	}

	t.printSummary()
}

// trainEpoch 한 에포크 학습
func (t *Trainer) trainEpoch(batches [][][]int) float64 {
	totalLoss := 0.0
	numBatches := 0

	for i, batch := range batches {
		if len(batch) == 0 {
			continue
		}

		// 손실 계산
		loss := 0.0
		for _, sequence := range batch {
			if len(sequence) < 2 {
				continue
			}

			// 간단한 손실 계산
			loss += float64(len(sequence)) * 0.1
		}

		// Learning rate 조정 (Warmup)
		lr := t.Config.LearningRate
		if t.State.Step < int64(t.Config.WarmupSteps) {
			warmupProgress := float64(t.State.Step) / float64(t.Config.WarmupSteps)
			lr *= warmupProgress
		}

		t.Optimizer.lr = lr
		totalLoss += loss
		numBatches++
		t.State.Step++

		// 진행률 출력
		if (i+1)%50 == 0 {
			avgLoss := totalLoss / float64(numBatches)
			fmt.Printf("  Batch %d: loss=%.4f (avg=%.4f)\n", i+1, loss, avgLoss)
		}
	}

	return totalLoss / float64(math.Max(1, float64(numBatches)))
}

// validateEpoch 검증
func (t *Trainer) validateEpoch(batches [][][]int) float64 {
	totalLoss := 0.0
	numBatches := 0

	for _, batch := range batches {
		if len(batch) == 0 {
			continue
		}

		loss := 0.0
		for _, sequence := range batch {
			if len(sequence) < 2 {
				continue
			}
			loss += float64(len(sequence)) * 0.1
		}

		totalLoss += loss
		numBatches++
	}

	return totalLoss / float64(math.Max(1, float64(numBatches)))
}

// printSummary 학습 요약 출력
func (t *Trainer) printSummary() {
	elapsed := time.Since(t.State.StartTime)
	stepsPerSec := float64(t.State.Step) / elapsed.Seconds()

	fmt.Printf("\n════════════════════════════════════════════════════════\n")
	fmt.Printf("📊 TRAINING SUMMARY\n")
	fmt.Printf("════════════════════════════════════════════════════════\n")
	fmt.Printf("Total steps:            %d\n", t.State.Step)
	fmt.Printf("Best validation loss:   %.4f\n", t.State.BestValLoss)
	fmt.Printf("Elapsed time:           %.1fs\n", elapsed.Seconds())
	fmt.Printf("Speed:                  %.1f steps/sec\n", stepsPerSec)
	fmt.Printf("Total patience:         %d/3\n", t.State.PatienceCount)
	fmt.Printf("\n✅ Training complete!\n")
}

// GetMetrics 현재 메트릭 반환
func (t *Trainer) GetMetrics() TrainingMetrics {
	elapsed := time.Since(t.State.StartTime)
	stepsPerSec := float64(t.State.Step) / elapsed.Seconds()

	improvement := 0.0
	if t.State.BestValLoss < math.Inf(1) {
		improvement = (t.State.BestValLoss - t.State.ValLoss) / t.State.BestValLoss * 100
	}

	return TrainingMetrics{
		Step:         t.State.Step,
		Epoch:        t.State.Epoch,
		Loss:         t.State.TotalLoss,
		ValLoss:      t.State.ValLoss,
		LearningRate: t.Config.LearningRate,
		GradNorm:     t.State.GradNorm,
		Speed:        stepsPerSec,
		Improvement:  improvement,
	}
}

// LoadCheckpoint 체크포인트에서 로드
func (t *Trainer) LoadCheckpoint(path string) error {
	// TODO: 체크포인트 로드 구현
	fmt.Printf("📂 Loading checkpoint from %s\n", path)
	return nil
}

// SaveCheckpoint 체크포인트 저장
func (t *Trainer) SaveCheckpoint(path string) error {
	// TODO: 체크포인트 저장 구현
	fmt.Printf("💾 Saving checkpoint to %s\n", path)
	t.State.LastSaveTime = time.Now()
	return nil
}

// EmbeddingModel 간단한 임베딩 모델
type EmbeddingModel struct {
	VocabSize int
	DModel    int
	Embedding [][]float64
}

// NewEmbeddingModel 새로운 모델 생성
func NewEmbeddingModel(vocabSize, dModel int) *EmbeddingModel {
	embedding := make([][]float64, vocabSize)
	for i := 0; i < vocabSize; i++ {
		embedding[i] = make([]float64, dModel)
		for j := 0; j < dModel; j++ {
			embedding[i][j] = (rand.Float64() - 0.5) * 2.0 / math.Sqrt(float64(dModel))
		}
	}

	return &EmbeddingModel{
		VocabSize: vocabSize,
		DModel:    dModel,
		Embedding: embedding,
	}
}

// Clone 모델 복사
func (m *EmbeddingModel) Clone() *EmbeddingModel {
	embedding := make([][]float64, m.VocabSize)
	for i := 0; i < m.VocabSize; i++ {
		embedding[i] = make([]float64, m.DModel)
		copy(embedding[i], m.Embedding[i])
	}

	return &EmbeddingModel{
		VocabSize: m.VocabSize,
		DModel:    m.DModel,
		Embedding: embedding,
	}
}

// Forward 전방향 전파
func (m *EmbeddingModel) Forward(ids []int) [][]float64 {
	result := make([][]float64, len(ids))
	for i, id := range ids {
		if id >= 0 && id < m.VocabSize {
			result[i] = make([]float64, m.DModel)
			copy(result[i], m.Embedding[id])
		}
	}
	return result
}

