package main

import (
	"fmt"
	"math"
	"math/rand"
	"time"
)

// ==================================================
// 서버 내 지속 학습 시스템
// ==================================================

// TrainingConfig 학습 설정
type TrainingConfig struct {
	VocabSize      int
	DModel         int
	BatchSize      int
	LearningRate   float64
	Epochs         int
	ValidateEvery  int
	SaveEvery      int
	MaxGradNorm    float64
	WeightDecay    float64
	WarmupSteps    int
}

// TrainingState 학습 상태
type TrainingState struct {
	Step           int64
	Epoch          int
	TotalLoss      float64
	BatchLoss      float64
	ValLoss        float64
	BestValLoss    float64
	LearningRate   float64
	GradNorm       float64
	PatienceCount  int
	StartTime      time.Time
	LastSaveTime   time.Time
}

// TrainingMetrics 학습 메트릭
type TrainingMetrics struct {
	Step        int64
	Epoch       int
	Loss        float64
	ValLoss     float64
	LearningRate float64
	GradNorm    float64
	Speed       float64 // steps/sec
	ETA         string
	Improvement float64
}

// Trainer 학습기
type Trainer struct {
	Config  TrainingConfig
	State   TrainingState
	Model   *EmbeddingModel
	Optimizer *Adam
	BestModel *EmbeddingModel
}

// NewTrainer 새로운 학습기 생성
func NewTrainer(config TrainingConfig) *Trainer {
	model := NewEmbeddingModel(config.VocabSize, config.DModel)
	optimizer := NewAdam(config.LearningRate, 0.9, 0.999, 1e-8)

	return &Trainer{
		Config: config,
		State: TrainingState{
			Step:         0,
			Epoch:        0,
			BestValLoss:  math.Inf(1),
			StartTime:    time.Now(),
			LastSaveTime: time.Now(),
		},
		Model:     model,
		Optimizer: optimizer,
		BestModel: model.Clone(),
	}
}

// Train 학습 실행
func (t *Trainer) Train(batches [][][]int, valBatches [][][]int) {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Continuous Training System            ║")
	fmt.Println("║  Server-side Learning Program + Checkpoint            ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	fmt.Printf("[CONFIG]\n")
	fmt.Printf("  VocabSize:     %d\n", t.Config.VocabSize)
	fmt.Printf("  DModel:        %d\n", t.Config.DModel)
	fmt.Printf("  BatchSize:     %d\n", t.Config.BatchSize)
	fmt.Printf("  LearningRate:  %.6f\n", t.Config.LearningRate)
	fmt.Printf("  Epochs:        %d\n", t.Config.Epochs)
	fmt.Printf("  WeightDecay:   %.6f\n", t.Config.WeightDecay)
	fmt.Printf("  WarmupSteps:   %d\n")
	fmt.Printf("  SaveEvery:     %d epochs\n\n", t.Config.SaveEvery)

	// 체크포인트 관리자 초기화
	checkpoint := NewCheckpoint("./checkpoints")

	for epoch := 1; epoch <= t.Config.Epochs; epoch++ {
		t.State.Epoch = epoch
		epochLoss := t.trainEpoch(batches)
		fmt.Printf("\n--- Epoch %d/%d ---\n", epoch, t.Config.Epochs)
		fmt.Printf("  Train Loss: %.4f\n", epochLoss)
		t.State.TotalLoss = epochLoss

		// 검증
		if epoch%1 == 0 {
			valLoss := t.validateEpoch(valBatches)
			t.State.ValLoss = valLoss
			fmt.Printf("  Val Loss:   %.4f", valLoss)

			// 최고 모델 저장
			if valLoss < t.State.BestValLoss {
				improvement := (t.State.BestValLoss - valLoss) / t.State.BestValLoss * 100
				fmt.Printf("  📈 %.2f%% improvement\n", improvement)
				t.State.BestValLoss = valLoss
				t.BestModel = t.Model.Clone()
				t.State.PatienceCount = 0

				// 최고 모델 자동 저장
				if _, err := checkpoint.SaveBest(t); err != nil {
					fmt.Printf("  ⚠️  Failed to save best model: %v\n", err)
				} else {
					fmt.Printf("  ✅ Best model saved\n")
				}
			} else {
				t.State.PatienceCount++
				fmt.Printf("  (patience: %d/3)\n", t.State.PatienceCount)

				// 조기 종료
				if t.State.PatienceCount >= 3 {
					fmt.Printf("\n⚠️ Early stopping at epoch %d\n", epoch)
					break
				}
			}
		}

		// 정기적 체크포인트 저장
		if t.Config.SaveEvery > 0 && epoch%t.Config.SaveEvery == 0 {
			if err := t.SaveCheckpoint(""); err != nil {
				fmt.Printf("  ⚠️  Failed to save checkpoint: %v\n", err)
			}
		}
	}

	t.printSummary()
}

// trainEpoch 한 에포크 학습
func (t *Trainer) trainEpoch(batches [][][]int) float64 {
	totalLoss := 0.0
	numBatches := 0

	for i, batch := range batches {
		if len(batch) == 0 {
			continue
		}

		// 손실 계산
		loss := 0.0
		for _, sequence := range batch {
			if len(sequence) < 2 {
				continue
			}

			// 간단한 손실 계산
			loss += float64(len(sequence)) * 0.1
		}

		// Learning rate 조정 (Warmup)
		lr := t.Config.LearningRate
		if t.State.Step < int64(t.Config.WarmupSteps) {
			warmupProgress := float64(t.State.Step) / float64(t.Config.WarmupSteps)
			lr *= warmupProgress
		}

		t.Optimizer.lr = lr
		totalLoss += loss
		numBatches++
		t.State.Step++

		// 진행률 출력
		if (i+1)%50 == 0 {
			avgLoss := totalLoss / float64(numBatches)
			fmt.Printf("  Batch %d: loss=%.4f (avg=%.4f)\n", i+1, loss, avgLoss)
		}
	}

	return totalLoss / float64(math.Max(1, float64(numBatches)))
}

// validateEpoch 검증
func (t *Trainer) validateEpoch(batches [][][]int) float64 {
	totalLoss := 0.0
	numBatches := 0

	for _, batch := range batches {
		if len(batch) == 0 {
			continue
		}

		loss := 0.0
		for _, sequence := range batch {
			if len(sequence) < 2 {
				continue
			}
			loss += float64(len(sequence)) * 0.1
		}

		totalLoss += loss
		numBatches++
	}

	return totalLoss / float64(math.Max(1, float64(numBatches)))
}

// printSummary 학습 요약 출력
func (t *Trainer) printSummary() {
	elapsed := time.Since(t.State.StartTime)
	stepsPerSec := float64(t.State.Step) / elapsed.Seconds()

	fmt.Printf("\n════════════════════════════════════════════════════════\n")
	fmt.Printf("📊 TRAINING SUMMARY\n")
	fmt.Printf("════════════════════════════════════════════════════════\n")
	fmt.Printf("Total steps:            %d\n", t.State.Step)
	fmt.Printf("Best validation loss:   %.4f\n", t.State.BestValLoss)
	fmt.Printf("Elapsed time:           %.1fs\n", elapsed.Seconds())
	fmt.Printf("Speed:                  %.1f steps/sec\n", stepsPerSec)
	fmt.Printf("Total patience:         %d/3\n", t.State.PatienceCount)
	fmt.Printf("\n✅ Training complete!\n")
}

// GetMetrics 현재 메트릭 반환
func (t *Trainer) GetMetrics() TrainingMetrics {
	elapsed := time.Since(t.State.StartTime)
	stepsPerSec := float64(t.State.Step) / elapsed.Seconds()

	improvement := 0.0
	if t.State.BestValLoss < math.Inf(1) {
		improvement = (t.State.BestValLoss - t.State.ValLoss) / t.State.BestValLoss * 100
	}

	return TrainingMetrics{
		Step:         t.State.Step,
		Epoch:        t.State.Epoch,
		Loss:         t.State.TotalLoss,
		ValLoss:      t.State.ValLoss,
		LearningRate: t.Config.LearningRate,
		GradNorm:     t.State.GradNorm,
		Speed:        stepsPerSec,
		Improvement:  improvement,
	}
}

// LoadCheckpoint 체크포인트에서 로드
func (t *Trainer) LoadCheckpoint(path string) error {
	cp := NewCheckpoint("./checkpoints")
	// 파일명에서 체크포인트 이름 추출
	name := path
	if name == "" {
		// 최신 체크포인트 자동 로드
		checkpoints, err := cp.List()
		if err != nil || len(checkpoints) == 0 {
			return fmt.Errorf("no checkpoints found")
		}
		name = checkpoints[0]["name"].(string)
	}

	fmt.Printf("📂 Loading checkpoint: %s\n", name)
	if err := cp.Load(t, name); err != nil {
		return err
	}

	fmt.Printf("✅ Checkpoint loaded successfully\n")
	fmt.Printf("   Epoch: %d | Step: %d | Val Loss: %.4f\n",
		t.State.Epoch, t.State.Step, t.State.ValLoss)
	return nil
}

// SaveCheckpoint 체크포인트 저장
func (t *Trainer) SaveCheckpoint(path string) error {
	cp := NewCheckpoint("./checkpoints")

	name := path
	if name == "" {
		// 기본값: 현재 epoch과 step으로 이름 지정
		name = fmt.Sprintf("checkpoint_epoch%d_step%d", t.State.Epoch, t.State.Step)
	}

	filepath, err := cp.Save(t, name)
	if err != nil {
		return fmt.Errorf("❌ Failed to save checkpoint: %w", err)
	}

	fmt.Printf("💾 Checkpoint saved: %s\n", filepath)
	fmt.Printf("   Epoch: %d | Step: %d | Val Loss: %.4f\n",
		t.State.Epoch, t.State.Step, t.State.ValLoss)

	t.State.LastSaveTime = time.Now()

	// 자동 정리: 최근 10개만 유지
	if err := cp.CleanupOldCheckpoints(10); err != nil {
		fmt.Printf("⚠️  Warning: Failed to cleanup old checkpoints: %w\n", err)
	}

	return nil
}

// EmbeddingModel 간단한 임베딩 모델
type EmbeddingModel struct {
	VocabSize int
	DModel    int
	Embedding [][]float64
}

// NewEmbeddingModel 새로운 모델 생성
func NewEmbeddingModel(vocabSize, dModel int) *EmbeddingModel {
	embedding := make([][]float64, vocabSize)
	for i := 0; i < vocabSize; i++ {
		embedding[i] = make([]float64, dModel)
		for j := 0; j < dModel; j++ {
			embedding[i][j] = (rand.Float64() - 0.5) * 2.0 / math.Sqrt(float64(dModel))
		}
	}

	return &EmbeddingModel{
		VocabSize: vocabSize,
		DModel:    dModel,
		Embedding: embedding,
	}
}

// Clone 모델 복사
func (m *EmbeddingModel) Clone() *EmbeddingModel {
	embedding := make([][]float64, m.VocabSize)
	for i := 0; i < m.VocabSize; i++ {
		embedding[i] = make([]float64, m.DModel)
		copy(embedding[i], m.Embedding[i])
	}

	return &EmbeddingModel{
		VocabSize: m.VocabSize,
		DModel:    m.DModel,
		Embedding: embedding,
	}
}

// Forward 전방향 전파
func (m *EmbeddingModel) Forward(ids []int) [][]float64 {
	result := make([][]float64, len(ids))
	for i, id := range ids {
		if id >= 0 && id < m.VocabSize {
			result[i] = make([]float64, m.DModel)
			copy(result[i], m.Embedding[id])
		}
	}
	return result
}

package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ==================================================
// Checkpoint 시스템
// ==================================================

// CheckpointData 체크포인트 데이터
type CheckpointData struct {
	Timestamp    time.Time              `json:"timestamp"`
	Epoch        int                    `json:"epoch"`
	Step         int64                  `json:"step"`
	Loss         float64                `json:"loss"`
	ValLoss      float64                `json:"val_loss"`
	BestValLoss  float64                `json:"best_val_loss"`
	LearningRate float64                `json:"learning_rate"`
	GradNorm     float64                `json:"grad_norm"`
	EmbeddingData [][]float64            `json:"embedding_data"`
	VocabSize    int                    `json:"vocab_size"`
	DModel       int                    `json:"d_model"`
	Metadata     map[string]interface{} `json:"metadata"`
}

// Checkpoint 체크포인트 관리자
type Checkpoint struct {
	dir string
}

// NewCheckpoint 새로운 체크포인트 관리자 생성
func NewCheckpoint(dir string) *Checkpoint {
	// 디렉토리 생성
	if err := os.MkdirAll(dir, 0755); err != nil {
		fmt.Printf("⚠️  Failed to create checkpoint directory: %v\n", err)
	}

	return &Checkpoint{dir: dir}
}

// Save 체크포인트 저장
func (c *Checkpoint) Save(trainer *Trainer, name string) (string, error) {
	// 타임스탬프가 없으면 생성
	if name == "" {
		name = fmt.Sprintf("checkpoint_epoch%d_step%d", trainer.State.Epoch, trainer.State.Step)
	}

	checkpoint := CheckpointData{
		Timestamp:    time.Now(),
		Epoch:        trainer.State.Epoch,
		Step:         trainer.State.Step,
		Loss:         trainer.State.TotalLoss,
		ValLoss:      trainer.State.ValLoss,
		BestValLoss:  trainer.State.BestValLoss,
		LearningRate: trainer.Config.LearningRate,
		GradNorm:     trainer.State.GradNorm,
		VocabSize:    trainer.Model.VocabSize,
		DModel:       trainer.Model.DModel,
		EmbeddingData: trainer.Model.Embedding,
		Metadata: map[string]interface{}{
			"vocab_size": trainer.Config.VocabSize,
			"d_model":    trainer.Config.DModel,
			"batch_size": trainer.Config.BatchSize,
			"patience":   trainer.State.PatienceCount,
		},
	}

	// JSON 파일 경로
	filepath := filepath.Join(c.dir, name+".json")

	// JSON 인코딩
	data, err := json.MarshalIndent(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal checkpoint: %w", err)
	}

	// 파일 쓰기
	if err := ioutil.WriteFile(filepath, data, 0644); err != nil {
		return "", fmt.Errorf("failed to write checkpoint: %w", err)
	}

	return filepath, nil
}

// Load 체크포인트 로드
func (c *Checkpoint) Load(trainer *Trainer, name string) error {
	// 파일 경로
	filepath := filepath.Join(c.dir, name+".json")

	// 파일 읽기
	data, err := ioutil.ReadFile(filepath)
	if err != nil {
		return fmt.Errorf("failed to read checkpoint: %w", err)
	}

	// JSON 디코딩
	var checkpoint CheckpointData
	if err := json.Unmarshal(data, &checkpoint); err != nil {
		return fmt.Errorf("failed to unmarshal checkpoint: %w", err)
	}

	// 모델 복원
	trainer.Model.Embedding = checkpoint.EmbeddingData
	trainer.Model.VocabSize = checkpoint.VocabSize
	trainer.Model.DModel = checkpoint.DModel

	// 학습 상태 복원
	trainer.State.Epoch = checkpoint.Epoch
	trainer.State.Step = checkpoint.Step
	trainer.State.TotalLoss = checkpoint.Loss
	trainer.State.ValLoss = checkpoint.ValLoss
	trainer.State.BestValLoss = checkpoint.BestValLoss
	trainer.State.LearningRate = checkpoint.LearningRate
	trainer.State.GradNorm = checkpoint.GradNorm

	return nil
}

// List 저장된 체크포인트 목록
func (c *Checkpoint) List() ([]map[string]interface{}, error) {
	files, err := ioutil.ReadDir(c.dir)
	if err != nil {
		return nil, fmt.Errorf("failed to read checkpoint directory: %w", err)
	}

	var checkpoints []map[string]interface{}

	for _, file := range files {
		if !strings.HasSuffix(file.Name(), ".json") {
			continue
		}

		filepath := filepath.Join(c.dir, file.Name())
		data, err := ioutil.ReadFile(filepath)
		if err != nil {
			continue
		}

		var checkpoint CheckpointData
		if err := json.Unmarshal(data, &checkpoint); err != nil {
			continue
		}

		info := map[string]interface{}{
			"name":          strings.TrimSuffix(file.Name(), ".json"),
			"epoch":         checkpoint.Epoch,
			"step":          checkpoint.Step,
			"loss":          checkpoint.Loss,
			"val_loss":      checkpoint.ValLoss,
			"timestamp":     checkpoint.Timestamp.Format("2006-01-02 15:04:05"),
			"size_mb":       float64(file.Size()) / (1024 * 1024),
			"learning_rate": checkpoint.LearningRate,
		}

		checkpoints = append(checkpoints, info)
	}

	// 최신순 정렬
	sort.Slice(checkpoints, func(i, j int) bool {
		ti := checkpoints[i]["timestamp"].(string)
		tj := checkpoints[j]["timestamp"].(string)
		return ti > tj
	})

	return checkpoints, nil
}

// Delete 체크포인트 삭제
func (c *Checkpoint) Delete(name string) error {
	filepath := filepath.Join(c.dir, name+".json")
	if err := os.Remove(filepath); err != nil {
		return fmt.Errorf("failed to delete checkpoint: %w", err)
	}
	return nil
}

// SaveBest 최고 모델 저장
func (c *Checkpoint) SaveBest(trainer *Trainer) (string, error) {
	return c.Save(trainer, fmt.Sprintf("best_model_valloss%.4f", trainer.State.BestValLoss))
}

// LoadBest 최고 모델 로드
func (c *Checkpoint) LoadBest(trainer *Trainer) error {
	checkpoints, err := c.List()
	if err != nil || len(checkpoints) == 0 {
		return fmt.Errorf("no checkpoints found")
	}

	// best_ 로 시작하는 최신 체크포인트 찾기
	for _, cp := range checkpoints {
		name := cp["name"].(string)
		if strings.HasPrefix(name, "best_") {
			return c.Load(trainer, name)
		}
	}

	return fmt.Errorf("no best model checkpoint found")
}

// CleanupOldCheckpoints 오래된 체크포인트 정리
func (c *Checkpoint) CleanupOldCheckpoints(keepLast int) error {
	checkpoints, err := c.List()
	if err != nil {
		return err
	}

	if len(checkpoints) <= keepLast {
		return nil
	}

	// 오래된 항목 삭제
	for i := keepLast; i < len(checkpoints); i++ {
		name := checkpoints[i]["name"].(string)
		if err := c.Delete(name); err != nil {
			fmt.Printf("⚠️  Failed to delete checkpoint %s: %v\n", name, err)
		}
	}

	return nil
}

// GetCheckpointInfo 체크포인트 정보 조회
func (c *Checkpoint) GetCheckpointInfo(name string) (map[string]interface{}, error) {
	filepath := filepath.Join(c.dir, name+".json")
	data, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}

	var checkpoint CheckpointData
	if err := json.Unmarshal(data, &checkpoint); err != nil {
		return nil, fmt.Errorf("failed to unmarshal checkpoint: %w", err)
	}

	info := map[string]interface{}{
		"name":           name,
		"timestamp":      checkpoint.Timestamp.Format("2006-01-02 15:04:05"),
		"epoch":          checkpoint.Epoch,
		"step":           checkpoint.Step,
		"loss":           checkpoint.Loss,
		"val_loss":       checkpoint.ValLoss,
		"best_val_loss":  checkpoint.BestValLoss,
		"learning_rate":  checkpoint.LearningRate,
		"grad_norm":      checkpoint.GradNorm,
		"vocab_size":     checkpoint.VocabSize,
		"d_model":        checkpoint.DModel,
		"metadata":       checkpoint.Metadata,
	}

	return info, nil
}

// ExportCheckpointStats 체크포인트 통계 내보내기
func (c *Checkpoint) ExportCheckpointStats() (string, error) {
	checkpoints, err := c.List()
	if err != nil {
		return "", err
	}

	// CSV 형식으로 생성
	csv := "Name,Epoch,Step,Loss,ValLoss,BestValLoss,LearningRate,Timestamp\n"

	for _, cp := range checkpoints {
		name := cp["name"]
		epoch := cp["epoch"]
		step := cp["step"]
		loss := cp["loss"]
		valLoss := cp["val_loss"]
		bestValLoss := cp["best_val_loss"]
		lr := cp["learning_rate"]
		timestamp := cp["timestamp"]

		csv += fmt.Sprintf("%v,%v,%v,%v,%v,%v,%v,%v\n",
			name, epoch, step, loss, valLoss, bestValLoss, lr, timestamp)
	}

	return csv, nil
}

// RestoreFromCheckpoint 체크포인트에서 복원
func (c *Checkpoint) RestoreFromCheckpoint(trainer *Trainer, checkpointName string) error {
	fmt.Printf("\n📂 Restoring from checkpoint: %s\n", checkpointName)

	if err := c.Load(trainer, checkpointName); err != nil {
		return err
	}

	fmt.Printf("✅ Successfully restored checkpoint\n")
	fmt.Printf("   Epoch: %d\n", trainer.State.Epoch)
	fmt.Printf("   Step: %d\n", trainer.State.Step)
	fmt.Printf("   Val Loss: %.4f\n", trainer.State.ValLoss)
	fmt.Printf("   Best Val Loss: %.4f\n", trainer.State.BestValLoss)

	return nil
}

// GetCheckpointPath 체크포인트 경로 반환
func (c *Checkpoint) GetCheckpointPath(name string) string {
	return filepath.Join(c.dir, name+".json")
}

// CheckpointStats 체크포인트 통계
type CheckpointStats struct {
	TotalCheckpoints  int                     `json:"total_checkpoints"`
	LatestCheckpoint  string                  `json:"latest_checkpoint"`
	BestCheckpoint    string                  `json:"best_checkpoint"`
	TotalStorageBytes int64                   `json:"total_storage_bytes"`
	Checkpoints       []map[string]interface{} `json:"checkpoints"`
}

// GetStats 전체 통계 조회
func (c *Checkpoint) GetStats() (CheckpointStats, error) {
	checkpoints, err := c.List()
	if err != nil {
		return CheckpointStats{}, err
	}

	stats := CheckpointStats{
		TotalCheckpoints: len(checkpoints),
		Checkpoints:      checkpoints,
	}

	if len(checkpoints) > 0 {
		stats.LatestCheckpoint = checkpoints[0]["name"].(string)

		// 최고 모델 찾기
		bestIdx := 0
		bestValLoss := checkpoints[0]["val_loss"].(float64)

		for i, cp := range checkpoints {
			if valLoss, ok := cp["val_loss"].(float64); ok {
				if valLoss < bestValLoss {
					bestValLoss = valLoss
					bestIdx = i
				}
			}
		}
		stats.BestCheckpoint = checkpoints[bestIdx]["name"].(string)
	}

	// 총 저장 공간 계산
	files, err := ioutil.ReadDir(c.dir)
	if err == nil {
		for _, file := range files {
			stats.TotalStorageBytes += file.Size()
		}
	}

	return stats, nil
}

// VersionModel 모델 버전 관리
type VersionModel struct {
	Version   string    `json:"version"`
	Timestamp time.Time `json:"timestamp"`
	Metrics   map[string]interface{} `json:"metrics"`
}

// SaveVersion 버전으로 저장
func (c *Checkpoint) SaveVersion(trainer *Trainer, versionName string) (string, error) {
	// 버전 디렉토리 생성
	versionDir := filepath.Join(c.dir, "versions")
	if err := os.MkdirAll(versionDir, 0755); err != nil {
		return "", fmt.Errorf("failed to create version directory: %w", err)
	}

	// 버전 체크포인트 저장
	name := fmt.Sprintf("v%s_epoch%d", versionName, trainer.State.Epoch)
	checkpoint := CheckpointData{
		Timestamp:    time.Now(),
		Epoch:        trainer.State.Epoch,
		Step:         trainer.State.Step,
		Loss:         trainer.State.TotalLoss,
		ValLoss:      trainer.State.ValLoss,
		BestValLoss:  trainer.State.BestValLoss,
		LearningRate: trainer.Config.LearningRate,
		GradNorm:     trainer.State.GradNorm,
		VocabSize:    trainer.Model.VocabSize,
		DModel:       trainer.Model.DModel,
		EmbeddingData: trainer.Model.Embedding,
		Metadata: map[string]interface{}{
			"version": versionName,
		},
	}

	filepath := filepath.Join(versionDir, name+".json")
	data, err := json.MarshalIndent(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal version: %w", err)
	}

	if err := ioutil.WriteFile(filepath, data, 0644); err != nil {
		return "", fmt.Errorf("failed to write version: %w", err)
	}

	return filepath, nil
}

// ListVersions 버전 목록 조회
func (c *Checkpoint) ListVersions() ([]map[string]interface{}, error) {
	versionDir := filepath.Join(c.dir, "versions")
	files, err := ioutil.ReadDir(versionDir)
	if err != nil {
		return nil, fmt.Errorf("no versions found: %w", err)
	}

	var versions []map[string]interface{}

	for _, file := range files {
		if !strings.HasSuffix(file.Name(), ".json") {
			continue
		}

		filepath := filepath.Join(versionDir, file.Name())
		data, err := ioutil.ReadFile(filepath)
		if err != nil {
			continue
		}

		var checkpoint CheckpointData
		if err := json.Unmarshal(data, &checkpoint); err != nil {
			continue
		}

		info := map[string]interface{}{
			"name":      strings.TrimSuffix(file.Name(), ".json"),
			"version":   checkpoint.Metadata["version"],
			"epoch":     checkpoint.Epoch,
			"val_loss":  checkpoint.ValLoss,
			"timestamp": checkpoint.Timestamp.Format("2006-01-02 15:04:05"),
		}

		versions = append(versions, info)
	}

	return versions, nil
}

// ExportModel 모델 내보내기 (간단한 텍스트 형식)
func (c *Checkpoint) ExportModel(trainer *Trainer, format string) (string, error) {
	if format == "json" {
		// JSON 형식
		checkpoint := CheckpointData{
			Timestamp:    time.Now(),
			Epoch:        trainer.State.Epoch,
			Step:         trainer.State.Step,
			VocabSize:    trainer.Model.VocabSize,
			DModel:       trainer.Model.DModel,
			EmbeddingData: trainer.Model.Embedding,
		}

		data, err := json.MarshalIndent(checkpoint, "", "  ")
		if err != nil {
			return "", fmt.Errorf("failed to marshal model: %w", err)
		}

		return string(data), nil
	}

	// CSV 형식
	csv := "vocab_id,embedding_values\n"
	for i, emb := range trainer.Model.Embedding {
		vals := ""
		for _, v := range emb {
			vals += fmt.Sprintf("%.6f,", v)
		}
		vals = strings.TrimSuffix(vals, ",")
		csv += fmt.Sprintf("%d,%s\n", i, vals)
	}

	return csv, nil
}

// ImportModel 모델 임포트
func (c *Checkpoint) ImportModel(trainer *Trainer, data []byte) error {
	var checkpoint CheckpointData
	if err := json.Unmarshal(data, &checkpoint); err != nil {
		return fmt.Errorf("failed to import model: %w", err)
	}

	trainer.Model.Embedding = checkpoint.EmbeddingData
	trainer.Model.VocabSize = checkpoint.VocabSize
	trainer.Model.DModel = checkpoint.DModel

	return nil
}

// CompareCheckpoints 체크포인트 비교
func (c *Checkpoint) CompareCheckpoints(name1, name2 string) (map[string]interface{}, error) {
	info1, err := c.GetCheckpointInfo(name1)
	if err != nil {
		return nil, fmt.Errorf("failed to get info for %s: %w", name1, err)
	}

	info2, err := c.GetCheckpointInfo(name2)
	if err != nil {
		return nil, fmt.Errorf("failed to get info for %s: %w", name2, err)
	}

	// 비교 결과
	comparison := map[string]interface{}{
		"checkpoint1": name1,
		"checkpoint2": name2,
		"epoch_diff":  info2["epoch"].(int) - info1["epoch"].(int),
		"step_diff":   info2["step"].(int64) - info1["step"].(int64),
		"loss_diff":   info2["loss"].(float64) - info1["loss"].(float64),
		"val_loss_diff": info2["val_loss"].(float64) - info1["val_loss"].(float64),
		"info1":       info1,
		"info2":       info2,
	}

	return comparison, nil
}

// AutoSaveCheckpoint 자동 저장 헬퍼
func (c *Checkpoint) AutoSaveCheckpoint(trainer *Trainer, saveEvery int) error {
	if trainer.State.Step%int64(saveEvery) == 0 && trainer.State.Step > 0 {
		_, err := c.Save(trainer, fmt.Sprintf("auto_step%d", trainer.State.Step))
		return err
	}
	return nil
}

