// NormalizeLogits 로짓 정규화 (확률로 변환)
func NormalizeLogits(logits []float64) []float64 {
	if len(logits) == 0 {
		return logits
	}

	// Softmax 계산
	maxLogit := logits[0]
	for _, l := range logits {
		if l > maxLogit {
			maxLogit = l
		}
	}

	sumExp := 0.0
	for _, l := range logits {
		sumExp += math.Exp(l - maxLogit)
	}

	probs := make([]float64, len(logits))
	for i, l := range logits {
		probs[i] = math.Exp(l-maxLogit) / sumExp
	}

	return probs
}

// SampleFromDistribution 분포에서 샘플링
func SampleFromDistribution(probs []float64, temperature float64) int {
	if len(probs) == 0 {
		return 0
	}

	// 온도 적용
	if temperature > 0 {
		adjusted := make([]float64, len(probs))
		sumExp := 0.0
		for i, p := range probs {
			if p > 0 {
				adjusted[i] = math.Pow(p, 1.0/temperature)
				sumExp += adjusted[i]
			}
		}

		for i := range adjusted {
			adjusted[i] /= sumExp
		}
		probs = adjusted
	}

	// 누적 확률
	cumulative := 0.0
	r := math.Sin(float64(len(probs))) // 간단한 난수 (실제: rand.Float64())
	for i, p := range probs {
		cumulative += p
		if r < cumulative {
			return i
		}
	}

	return len(probs) - 1
}

